import { Component, inject, input, output, signal } from '@angular/core';
import { HttpErrorResponse } from '@angular/common/http';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { InvoiceService, InvoiceSummary } from './invoice.service';
import { Currency, TWO_DECIMALS, symbolOf } from './invoice-format';

// Refunds the client's unused credit: an amount more than zero with at most two decimals, and the
// date it was refunded. It comes out of the oldest payment's credit first; the server refuses a
// date after today or before a payment it would come from, or more than the client's credit.
@Component({
  selector: 'app-refund-form',
  imports: [ReactiveFormsModule],
  template: `
    <form [formGroup]="form" (ngSubmit)="refund()" aria-label="Refund unused credit" novalidate>
      <label for="refund-amount">Refund ({{ symbolOf(currency()) }})</label>
      <input
        id="refund-amount"
        data-testid="refund-form-amount"
        inputmode="decimal"
        formControlName="amount"
        required
      />
      <label for="refund-date">Refunded on</label>
      <input id="refund-date" type="date" data-testid="refund-form-date" formControlName="date" required />
      <button type="submit" data-testid="refund-form-submit" [disabled]="saving()">Refund credit</button>
      @if (error()) {
        <p role="alert" data-testid="refund-form-error">{{ error() }}</p>
      }
    </form>
  `,
})
export class RefundForm {
  private readonly service = inject(InvoiceService);

  readonly clientId = input.required<number>();
  // The currency the client is billed in, which the refund is in.
  readonly currency = input<Currency>('USD');
  protected readonly symbolOf = symbolOf;
  // The client's invoices after a refund.
  readonly refunded = output<InvoiceSummary[]>();

  protected readonly saving = signal(false);
  protected readonly error = signal('');

  protected readonly form = new FormGroup({
    amount: new FormControl('', { nonNullable: true }),
    date: new FormControl('', { nonNullable: true }),
  });

  protected refund(): void {
    const raw = this.form.getRawValue();
    const amount = raw.amount.trim().replace(/^\$/, '');
    const date = raw.date.trim();
    const problems: string[] = [];
    if (!amount) {
      problems.push('Enter an amount.');
    } else if (!TWO_DECIMALS.test(amount)) {
      problems.push('The amount must be a number with at most two decimals.');
    } else if (Number(amount) <= 0) {
      problems.push('The amount must be more than zero.');
    }
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
      problems.push('Enter the date it was refunded.');
    }
    if (problems.length > 0) {
      this.form.markAllAsTouched();
      this.error.set(problems.join(' '));
      return;
    }
    this.saving.set(true);
    this.error.set('');
    this.service.refundCredit(this.clientId(), { amount, date }).subscribe({
      next: (list) => {
        this.form.reset();
        this.saving.set(false);
        this.refunded.emit(list);
      },
      error: (e: HttpErrorResponse) => {
        const detail: unknown = e.error?.detail;
        this.error.set(typeof detail === 'string' && detail ? detail : 'The refund could not be made.');
        this.saving.set(false);
      },
    });
  }
}
package net.officefloor.hq.app;

import java.math.BigDecimal;
import java.math.MathContext;
import java.sql.Date;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.clients.Currency;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;

/**
 * The workspace's exchange rates: the US dollars one unit of each currency is worth, stored as the
 * {@code usd_per_<code>} settings. A US dollar is worth one; a currency with no rate set is taken
 * at par. Dated rates (the {@code fx_rate} table) take over from their date on: something converted on
 * a date uses the latest dated rate on or before it, or the standing rate before any. Invoices read
 * their client's rates themselves (see Invoice).
 */
@Service
public class ExchangeRates {

    /** The prefix of the setting holding a currency's rate, followed by its code (usd_per_EUR). */
    public static final String USD_PER = "usd_per_";

    private final JdbcTemplate jdbc;

    public ExchangeRates(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Every rate set, by currency code. */
    public Map<String, BigDecimal> all() {
        Map<String, BigDecimal> rates = new LinkedHashMap<>();
        jdbc.queryForList("SELECT name, setting_value FROM app_setting WHERE name LIKE ? ORDER BY name", USD_PER + "%")
                .forEach(r -> rates.put(((String) r.get("NAME")).substring(USD_PER.length()),
                        new BigDecimal((String) r.get("SETTING_VALUE"))));
        return rates;
    }

    /** A dated rate: from the date on, the US dollars one unit of the currency is worth. */
    public record Dated(LocalDate from, Currency currency, BigDecimal usdPer) {
    }

    /** Every dated rate, by date then currency. */
    public List<Dated> dated() {
        return jdbc.query("SELECT from_date, currency, usd_per FROM fx_rate ORDER BY from_date, currency, id",
                (rs, n) -> new Dated(rs.getDate(1).toLocalDate(), Currency.of(rs.getString(2)), rs.getBigDecimal(3)));
    }

    /** Adds a dated rate. */
    public void addDated(LocalDate from, Currency currency, BigDecimal usdPer) {
        jdbc.update("INSERT INTO fx_rate (from_date, currency, usd_per) VALUES (?, ?, ?)", Date.valueOf(from),
                currency.name(), usdPer);
    }

    /**
     * The US dollars one unit of the currency is worth on the date: the latest dated rate on or before
     * it, otherwise the standing rate (see {@link #usdPer(Currency)}).
     */
    public BigDecimal usdPer(Currency currency, LocalDate on) {
        if (currency == Currency.USD) {
            return BigDecimal.ONE;
        }
        return jdbc.queryForList("SELECT usd_per FROM fx_rate WHERE currency = ? AND from_date <= ? ORDER BY from_date DESC, id DESC LIMIT 1",
                BigDecimal.class, currency.name(), Date.valueOf(on)).stream().findFirst().orElseGet(() -> usdPer(currency));
    }

    /** The US dollars one unit of the currency is worth: one for the dollar or a currency with no rate set. */
    public BigDecimal usdPer(Currency currency) {
        if (currency == Currency.USD) {
            return BigDecimal.ONE;
        }
        return jdbc.queryForList("SELECT setting_value FROM app_setting WHERE name = ?", String.class, USD_PER + currency.name())
                .stream().findFirst().map(v -> new BigDecimal(v.trim())).orElse(BigDecimal.ONE);
    }

    /**
     * The amount paid in one currency converted into another through US dollars: amount x (dollars per
     * unit paid) / (dollars per unit of the other), at the rates in force on the date, rounded half up
     * to the other's step.
     */
    public BigDecimal convert(BigDecimal amount, Currency from, Currency to, LocalDate on) {
        if (from == to) {
            return amount.setScale(to.scale());
        }
        return to.roundToStep(amount.multiply(usdPer(from, on)).divide(usdPer(to, on), MathContext.DECIMAL128));
    }
}
package net.officefloor.hq.app.clients;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.text.DecimalFormat;
import java.text.DecimalFormatSymbols;
import java.util.Locale;

/**
 * A currency a client is billed in, with the symbol its amounts are shown with and how many decimals
 * they have: yen have none, so every amount for a yen client is in whole yen.
 */
public enum Currency {
    USD("$", 2), EUR("€", 2), GBP("£", 2), JPY("¥", 0), CHF("CHF ", 2);

    private final String symbol;
    private final int scale;

    Currency(String symbol, int scale) {
        this.symbol = symbol;
        this.scale = scale;
    }

    /** How many decimals an amount has: 2 (to the cent), or 0 for yen. */
    public int scale() {
        return scale;
    }

    /** Whether the amount is whole in this currency: no more decimals than {@link #scale()}. */
    public boolean isWhole(BigDecimal amount) {
        return amount.stripTrailingZeros().scale() <= scale;
    }

    /**
     * The amount rounded half up to this currency's step: whole yen, 0.05 for Swiss francs, otherwise
     * the cent.
     */
    public BigDecimal roundToStep(BigDecimal amount) {
        BigDecimal step = this == CHF ? new BigDecimal("0.05") : BigDecimal.ONE.movePointLeft(scale);
        return amount.divide(step, 0, RoundingMode.HALF_UP).multiply(step).setScale(scale);
    }

    /** The amount with its symbol and thousands separators, e.g. €1,234.50 or ¥1,235. */
    public String format(BigDecimal amount) {
        DecimalFormat number = new DecimalFormat(scale == 0 ? "#,##0" : "#,##0.00",
                DecimalFormatSymbols.getInstance(Locale.US));
        BigDecimal rounded = amount.setScale(scale, RoundingMode.HALF_UP);
        return (rounded.signum() < 0 ? "-" : "") + symbol + number.format(rounded.abs());
    }

    /** The currency with the code, or null when there is no such currency. */
    public static Currency of(String code) {
        for (Currency c : values()) {
            if (c.name().equals(code)) {
                return c;
            }
        }
        return null;
    }

    /** The currency with the code; US dollars when there is none. */
    public static Currency orUsd(String code) {
        Currency c = code == null ? null : of(code);
        return c == null ? USD : c;
    }
}
-- Dated exchange rates: from a date on, the US dollars one unit of the currency is worth. Something
-- converted on a date uses the latest dated rate on or before it, or the standing usd_per_<code>
-- setting before any.
CREATE TABLE fx_rate (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    from_date DATE           NOT NULL,
    currency  VARCHAR(3)     NOT NULL,
    usd_per   DECIMAL(19, 8) NOT NULL
);
-- How much of a payment's unused credit has been refunded to the client: it can no longer be used.
ALTER TABLE payment ADD COLUMN refunded DECIMAL(19, 2) DEFAULT 0 NOT NULL;
